using System.Text.Json;
using EqlTracker.Core;

internal static class OctoberContentTests
{
    internal static void Register(Action<string,Action> test)
    {
        void Check(bool ok,string reason="October content assertion failed"){if(!ok)throw new Exception(reason);}
        void Test(string name,Action run)=>test("October content: "+name,run);
        PetContextCatalog Summons()=>PetContextCatalog.Load(Path.Combine(AppContext.BaseDirectory,"data/pet-context.json"));
        CharacterProfile Profile()=>new(){Loadouts=[new(){Name="Synthetic",Classes=["MAG","CLR","MNK"],Level=50,Race="Ayr'Haeth",RaceLevel=7}],SelectedLoadout="Synthetic"};
        List<PetComparisonResult> Run(CharacterProfile p)=>PetComparisonEngine.Evaluate(p,new(){PetType="Monster",PetLevel=42},new(),Summons(),PetBuffCatalog.References(),[],PetEquipmentMode.IntendedSlots,CancellationToken.None);
        Test("offline zones and source documents are idempotent",()=>{var c=new Catalog();OctoberContent.Apply(c);OctoberContent.Apply(c);Check(c.Zones.Count==3&&c.Documents.Count==2&&c.Quests.Count==0&&c.Items.Count==0);Check(OctoberContent.Zones.All(z=>z.Source==OctoberContent.Announcement&&z.Access.Length>0));});
        Test("new zone aliases preserve distinct areas",()=>{Check(Identity.ZoneKey("The Nektropos Castle (Solo)")==Identity.ZoneKey("Nektropos Castle"));Check(Identity.ZoneKey("Nektropos Castle Undercroft")==Identity.ZoneKey("Nektropos Undercroft"));Check(Identity.ZoneKey("Lake Nerius Trading Center")==Identity.ZoneKey("Lake Nerius"));Check(Identity.ZoneKey("Nektropos Castle")!=Identity.ZoneKey("Nektropos Undercroft"));});
        Test("Classic-era inference does not manufacture item access",()=>{var item=new ItemDefinition{Sources=[new(){Zone="Lake Nerius"}]};ItemExpansionEvidence.Apply(item);Check(item.IntroducedExpansion=="Unknown"&&item.ExpansionProvenance.Inferred&&item.ExpansionProvenance.Expansion=="Classic");Check(OctoberContent.ZoneHelp("Nektropos Castle").Contains("inferred"));});
        foreach(string name in new[]{"Half Dark Elf","Half Dark Elves","Ayr’Haeth","ayr'haeth"})Test("race alias "+name,()=>Check(RaceNames.Canonical(name)=="Ayr'Haeth"));
        Test("race restrictions never inherit parent races",()=>{Check(!RaceNames.Allows(["DEF HEF"],"Half Dark Elf"));Check(!RaceNames.Allows(["Half Dark Elf HIE"],"Dark Elf"));Check(RaceNames.Allows(["Half Dark Elf HIE"],"Ayr'Haeth"));Check(RaceNames.Allows(["HUM HIE DEF"],"High Elf"));Check(!RaceNames.Allows(["HUM HIE"],""));Check(RaceNames.Allows(["ALL"],""));Check(!RaceNames.Allows(["HUM"],"Unknown race"));});
        Test("race level persists separately and legacy level stays unknown",()=>{var p=Profile();var copy=JsonSerializer.Deserialize<CharacterProfile>(JsonSerializer.Serialize(p))!;Check(copy.ActiveLoadout.RaceLevel==7&&copy.ActiveLoadout.Level==50);Check(JsonSerializer.Deserialize<LoadoutProfile>("{\"Level\":50,\"Race\":\"High Elf\"}")!.RaceLevel==null);});
        Test("who race observation does not become a race-level observation",()=>{var p=Profile();var engine=new CombatEngine(p);var parser=new LogParser("ExampleHero");engine.Process(parser.Parse("[Thu Oct 22 21:00:00 2026] [50 MAG/CLR/MNK] ExampleHero (Half Dark Elf) ZONE: Lake Nerius")!);Check(p.ActiveLoadout.Race=="Ayr'Haeth"&&p.ActiveLoadout.RaceLevel==7&&p.ActiveLoadout.Level==50);engine.Process(parser.Parse("[Thu Oct 22 21:00:01 2026] [50 MAG/CLR/MNK] ExampleHero (High Elf)")!);Check(p.ActiveLoadout.Race=="High Elf"&&p.ActiveLoadout.RaceLevel==null);Check(parser.Parse("[Thu Oct 22 21:00:02 2026] [50 WAR] Somebody (Half Dark Elf)")!.Race==null);});
        Test("Monster summon levels and saved identifiers",()=>{var s=Summons();var a=s.Find("Monster","Monster Summoning I")!;var b=s.Find("Monster","Summon Monster II")!;Check(a.RequiredLevel==30&&a.BasePetLevel==29&&a.Id=="Monster|MAG|Monster Summoning I");Check(b.RequiredLevel==50&&b.BasePetLevel==42&&b.Revision==168338);Check(s.Estimate(new(){PetType="Monster",SummonSpell=a.Name,SummonRank=10},35).Level==35);});
        Test("Monster class and level eligibility",()=>{var p=Profile();Check(PetComparisonEngine.Eligible(Summons(),p.ActiveLoadout).Count(s=>s.PetType=="Monster")==2);p.ActiveLoadout.Level=30;Check(PetComparisonEngine.Eligible(Summons(),p.ActiveLoadout).Count(s=>s.PetType=="Monster")==1);p.ActiveLoadout.Level=29;Check(!PetComparisonEngine.Eligible(Summons(),p.ActiveLoadout).Any(s=>s.PetType=="Monster"));p.ActiveLoadout.Level=50;p.ActiveLoadout.Classes=["NEC","BST","WAR"];Check(!PetComparisonEngine.Eligible(Summons(),p.ActiveLoadout).Any(s=>s.PetType=="Monster"));});
        Test("Monster grants WAR BER plus owner access consistently",()=>{var owner=Profile().ActiveLoadout;owner.PetType="Monster";foreach(string c in new[]{"WAR","BER","CLR"}){var item=new ItemDefinition{Classes=[c],Slots=["PRIMARY"],MetadataComplete=true};Check(GearScorer.Eligibility(item,owner,true,null,new())=="Eligible");Check(PetComparisonEngine.Access(item,owner,"Monster")!=PetClassAccess.Incompatible);}Check(!GearScorer.EligibleClasses(owner,false).Contains("BER"));});
        Test("Monster correlation requires ownership and a successful attempt",()=>{var at=new DateTime(2026,10,22,20,0,0);var detector=new PetElementDetector();var p=Profile();detector.Process(new(){Time=at,PlayerCast="Monster Summoning II"},p);detector.Process(new(){Time=at.AddSeconds(11),PetActivity="Outsider"},p);Check(p.PetIdentities.Count==0);p.PetIdentities.Add(new(){Name="Mistling",From=at.AddSeconds(10)});detector.Process(new(){Time=at.AddSeconds(12),PetName="Mistling"},p);Check(p.PetIdentities[0].Element=="Monster"&&p.PetIdentities[0].ElementConfidence=="Correlated summon");detector.Process(new(){Time=at.AddSeconds(13),CastFailed=true,FailedSpell="Monster Summoning II"},p);Check(p.PetIdentities[0].Element=="Unknown");});
        Test("failed summons and generic Frenzy do not identify Monster",()=>{var at=new DateTime(2026,10,22);var d=new PetElementDetector();var p=Profile();p.PetIdentities.Add(new(){Name="Mistling",From=at.AddSeconds(10)});d.Process(new(){Time=at,PlayerCast="Monster Summoning I"},p);d.Process(new(){Time=at.AddSeconds(1),CastFailed=true,FailedSpell="Monster Summoning I"},p);d.Process(new(){Time=at.AddSeconds(12),PetName="Mistling",ActivitySpell="Frenzy"},p);Check(!PetElementDetector.HasFamilyIcon(p.PetIdentities[0].Element)&&p.PetIdentities[0].ElementConfidence=="Unknown");Check(PetElementDetector.SummonElement("Monster Summoning II +4")=="Monster"&&PetElementDetector.SummonElement("Monster Summoning IV")==null);});
        Test("comparison offers Monster without fabricating baseline HP mana or DPS",()=>{var p=Profile();string before=JsonSerializer.Serialize(p);var row=Run(p).Single(r=>r.Pet=="Monster");Check(row.Definition.Classes.SequenceEqual(new[]{"WAR","BER"})&&row.Hp==null&&row.DisplayDps==null&&row.Spell.Name=="Monster Summoning II");Check(row.Missing.Any(m=>m.Contains("unverified")));Check(JsonSerializer.Serialize(p)==before);});
        Test("patch and race context reject old benchmarks and stale identities",()=>{var p=Profile();var row=Run(p).Single(r=>r.Pet=="Monster");var old=new PetBenchmark{Pet="Monster",ContextConfirmed=true,ContextKey=PetBenchmarks.Context(row),MechanicsVersion="EQL-2026-10-13/pet-comparison-v3",Dps=100};Check(PetBenchmarks.Matching(row,[old])==null);var current=new PetBenchmark{ContextConfirmed=true,ContextKey=PetBenchmarks.Context(row),Dps=90};Check(PetBenchmarks.Matching(row,[current])==current);p.ActiveLoadout.RaceLevel=8;var next=Run(p).Single(r=>r.Pet=="Monster");Check(row.Scenario.InputKey!=next.Scenario.InputKey&&PetBenchmarks.Matching(next,[current])==null);});
        Test("published mechanics distinguish dependencies from coefficients",()=>{Check(OctoberContent.Mechanics.Single(m=>m.Name=="Pet stamina").Value==null);Check(OctoberContent.Mechanics.Single(m=>m.Name=="Pet casting stats").Value==null);Check(OctoberContent.Mechanics.Single(m=>m.Name=="Taunt on").Value==75);Check(OctoberContent.Mechanics.Single(m=>m.Name=="Pet command hold").Value==6);Check(PetDefinition.Version.Contains("2026-10-22")&&RankedItemStats.Resolve(new(){Stats=new(){["Damage"]=16,["Delay"]=22}},4).Stats["Damage"]==22);});
        Test("history separates patch eras without changing damage or duration",()=>{var fights=new[]{new Encounter{Start=new(2026,10,21,20,0,0),End=new(2026,10,21,20,0,10),PetType="Monster",Finished=true,PetDamage=100},new Encounter{Start=new(2026,10,22,20,0,0),End=new(2026,10,22,20,0,10),PetType="Monster",Finished=true,PetDamage=200}};string before=JsonSerializer.Serialize(fights);var rows=PetComparisonEngine.History(fights);Check(rows.Count==2&&rows.Sum(r=>r.Damage)==300&&rows.Sum(r=>r.Seconds)==20&&rows.Any(r=>r.Conditions.Contains("Before October 22")));Check(before==JsonSerializer.Serialize(fights));});
        Test("older encounters cannot acquire the current mechanics version",()=>{var row=Run(Profile()).Single(r=>r.Pet=="Monster");var fight=new Encounter{Start=new(2026,10,21,20,0,0),End=new(2026,10,21,20,0,10),PetType="Monster",Finished=true,PetDamage=100};var b=PetBenchmarks.FromFights(row,[fight],"Historical synthetic sample",true);Check(b.Dps==10&&b.MechanicsVersion!=PetDefinition.Version&&PetBenchmarks.Matching(row,[b])==null);});
        Test("client spell files are hashed with fail-closed format validation",()=>{string file=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+"-synthetic-spells.txt");try{File.WriteAllText(file,"invalid format");var parsed=PetClientSpellAdapter.ParseFile(file,CancellationToken.None);Check(parsed.Version.Contains("sha256:")&&parsed.Status.Contains("rejected"));using var cancel=new CancellationTokenSource();cancel.Cancel();bool rejected=false;try{PetClientSpellAdapter.ParseFile(file,cancel.Token);}catch(OperationCanceledException){rejected=true;}Check(rejected);}finally{File.Delete(file);}});
        Test("cancelled comparison cannot publish a result",()=>{using var cancel=new CancellationTokenSource();cancel.Cancel();bool rejected=false;try{PetComparisonEngine.Evaluate(Profile(),new(),new(),Summons(),PetBuffCatalog.References(),[],PetEquipmentMode.IntendedSlots,cancel.Token);}catch(OperationCanceledException){rejected=true;}Check(rejected);});
    }
}
